import {operationGuide} from './feedback.mjs';
import {choiceLabel} from './zh.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function table(e,handOwner,selected=[],attackFrom=null){
 const s=e.s,p=s.prompt,active=s.active,guide=operationGuide(e,selected);
 const card=(c,small=false)=>{const d=e.def(c),chosen=selected.includes(c.uid),valid=p?.candidates?.includes(c.uid)&&(chosen||e.targetAllowed(p,c.uid,selected)),target=attackFrom&&e.canAttack(s.cards[attackFrom],c),don=c.id==='DON';const status=c.attached?`附加于 ${e.name(s.cards[c.attached])}`:c.rested?'横置':'可用';return `<button class="table-card ${don?'don-card':''} ${c.rested?'rested':''} ${chosen?'picked':''} ${valid||target?'eligible':''} ${small?'small':''}" data-board="${c.uid}" aria-pressed="${chosen}" aria-label="${esc(don?'DON!!，'+status:e.name(c))}${!don&&c.rested?'，横置':''}">${don?`<span class="don-face"><b>DON!!</b><span>${esc(status)}</span></span>`:`<img src="${d.thumbnail||d.image}" alt="${esc(e.name(c))}" loading="lazy">`}${chosen?`<span class="selection-number">${selected.indexOf(c.uid)+1}</span>`:''}${['field','leader'].includes(c.zone)?`<span class="power">${e.power(c)}</span>`:''}${!don&&e.attached(c).length?`<span class="attached">DON!! ×${e.attached(c).length}</span>`:''}${!don&&c.rested?'<span class="rest-label">横置</span>':''}</button>`};
 const side=(o,compact)=>{const pl=s.players[o],leader=e.list(o,'leader')[0];return `<section class="play-side ${compact?'opponent':'self'} ${o?'blue-side':'red-side'}"><div class="side-title"><strong>${e.label(o)} ${o===active?' · 当前回合':''}</strong><span data-deck-anchor="${o}">手牌 ${pl.hand.length} · 牌库 ${pl.deck.length}</span><button data-zone="${o}:trash">弃牌 ${pl.trash.length}</button></div><div class="characters">${e.list(o,'field').map(c=>card(c,compact)).join('')}${Array.from({length:5-pl.field.length},(_,i)=>`<div class="empty-slot"><span>${i+pl.field.length+1}</span></div>`).join('')}</div><div class="lower-lane"><div class="don-pile" aria-label="场上 DON!! ${pl.don.length} 张"><div class="don-stack"><i></i><i></i><i></i></div><strong>DON!!</strong><span>场上 ${pl.don.length} 张</span></div><div class="don-totals"><div class="don-count ready"><strong>${e.readyDon(o).length}</strong><span>可用</span></div><div class="don-count spent"><strong>${e.restDon(o).length}</strong><span>横置</span></div><div class="don-count allocated"><strong>${e.don(o).filter(d=>d.attached).length}</strong><span>附加</span></div></div><div class="leader-slot">${card(leader,compact)}<small>领袖</small></div><div class="stage-slot"><span class="stage-title">舞台区</span>${e.list(o,'stage').map(c=>card(c)).join('')||'<div class="stage-empty">暂无舞台</div>'}</div><div class="life-area" data-life-anchor="${o}"><strong>${pl.life.length}</strong><span>生命</span><div class="life-stack">${pl.life.map((u,i)=>`<i style="--i:${i}"></i>`).join('')}</div></div></div></section>`};
 let controls='';
 if(p){
  let buttons='';
  if(p.type==='mulligan')buttons='<button data-answer="redraw">全部重抽</button><button class="primary" data-answer="keep">保留起手</button>';
  if(p.type==='confirmEffect')buttons=`${p.noCancel?'':'<button data-answer="no">取消</button>'}<button class="primary" data-answer="yes">确认执行</button>`;
  if(p.type==='optional'||p.type==='lifeTrigger'||p.type==='replacement')buttons=`<button data-answer="no">${p.type==='lifeTrigger'?'加入手牌':'不发动'}</button><button class="primary" data-answer="yes">发动效果</button>`;
  if(p.type==='counter')buttons='<button class="primary" data-answer="finish">结束反击，结算战斗</button>';
  if(p.type==='endOrder')buttons=p.entries.map((x,i)=>`<button data-answer="${i}">${esc(e.name(s.cards[x.uid]))} · 效果 ${x.index+1}</button>`).join('');
  if(p.type==='choice')buttons=p.choices.map((x,i)=>`<button data-answer="${i}">${esc(choiceLabel(x.ButtonText))}</button>`).join('');
  if(p.type==='peek')buttons=`${card(s.cards[p.peek])}<button class="primary" data-answer="confirm">已查看，继续</button>`;
  if(p.candidates)buttons=`<span>已选 ${selected.length} / ${p.max}</span>${p.cancelAllowed?'<button data-answer="cancelEffect">取消此效果</button>':''}<button class="primary" data-confirmtargets ${selected.length<p.min?'disabled':''}>${selected.length?'确认选择':p.type==='block'?'不阻挡':'不选择目标'}</button>`;
  const hiddenCandidates=p.candidates?.filter(u=>!['leader','field','stage','hand'].includes(s.cards[u].zone))||[];
  controls=`<section class="decision" role="region" aria-label="当前选择"><div><span class="decision-owner">${e.label(p.owner)} 操作</span><strong>${esc(p.title)}</strong>${guide.source?`<span class="effect-source">${esc(guide.source)}</span>`:''}</div>${guide.uid?`<button data-detailuid="${guide.uid}">查看中文效果</button>`:''}<div class="actions">${buttons}</div>${hiddenCandidates.length?`<div class="selection-cards">${hiddenCandidates.map(u=>card(s.cards[u])).join('')}</div>`:''}</section>`;
 }else if(s.winner!==null)controls=`<section class="decision"><strong>${e.label(s.winner)} 获胜</strong><button data-page="setup" class="primary">再练习一局</button></section>`;
 else controls=`<section class="turn-controls"><span>${attackFrom?'点击亮起的对方领袖或角色，选择攻击目标。':'点选手牌登场，或点场上卡牌附加 DON!!、攻击和发动效果。'}</span>${attackFrom?'<button data-cancelattack>取消攻击</button>':'<button class="primary" data-gamecommand="endTurn">结束回合</button>'}</section>`;
 const battle=s.battle?`<div class="combat-strip"><span>${esc(e.name(s.cards[s.battle.attacker]))} <b>${e.power(s.cards[s.battle.attacker])}</b></span><span>VS</span><span>${esc(e.name(s.cards[s.battle.target]))} <b>${e.power(s.cards[s.battle.target])+s.battle.counter}</b></span></div>`:'';
 const statusPanel=`<section class="console-status" role="status" aria-live="polite"><div class="table-head"><div><div class="eyebrow">SOLO · ${s.phase==='mulligan'?'起手准备':`第 ${s.turn} 回合`}</div><h2>对战练习</h2></div><div class="actions"><button data-gamecommand="undo" ${!e.history.length?'disabled':''}>撤销</button><button data-log>记录</button></div></div><section class="operation-guide"><div><strong>${e.label(guide.owner)} · ${guide.phase}</strong>${guide.source?`<span>正在结算：${esc(guide.source)}</span>`:''}</div><p>${esc(guide.detail)}</p></section></section>`;
 return `<div class="table-layout"><div class="game-board">${side(1,true)}<div class="table-divider"><span>ONE PIECE CARD GAME</span></div>${side(0,false)}</div><div class="play-console">${battle}${controls}<section class="hand-area"><div class="side-title"><strong>${e.label(handOwner)} 的手牌</strong><span>${s.players[handOwner].hand.length} 张</span></div><div class="hand-cards" style="--hand-overlaps:${Math.max(0,s.players[handOwner].hand.length-1)}">${e.list(handOwner,'hand').map(c=>card(c)).join('')||'<p class="muted">手牌为空</p>'}</div></section><section class="hover-preview" id="hover-preview" aria-live="polite"><p>将鼠标移到手牌、角色、领袖或舞台牌上，即可在这里查看中文效果。</p></section><p class="notice">自动结算开发预览 · 特殊效果仍在迁移与验证</p>${statusPanel}</div></div>`;
}
